/**
 * Validiert Geminis JSON, korrigiert Deadlines und normalisiert Subtasks.
 * @returns {Array<{json: object}>} Validierte Ticketdaten
 */
const response = $input.first().json;
const source = $('Gemini-Prompt erstellen').first().json;
const rawText = response.candidates?.[0]?.content?.parts?.[0]?.text;
if (!rawText) throw new Error('Gemini hat keine auswertbare Textantwort geliefert.');

const cleanedText = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
let ticket;
try { ticket = JSON.parse(cleanedText); }
catch (error) { throw new Error(`Gemini-Antwort ist kein gültiges JSON: ${error.message}`); }

const allowedCategories = ['Bug', 'User Story', 'Technical Task'];
const allowedPriorities = ['urgent', 'medium', 'low'];
if (!ticket.title || !ticket.description) throw new Error('Titel oder Beschreibung fehlt.');
if (!allowedCategories.includes(ticket.category)) ticket.category = 'Technical Task';
if (!allowedPriorities.includes(ticket.priority)) ticket.priority = 'medium';

function getTodayInZurich() {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/Zurich', day: '2-digit', month: '2-digit', year: 'numeric'
  }).formatToParts(new Date());
  const values = Object.fromEntries(parts.map((part) => [part.type, part.value]));
  return {
    formatted: `${values.day}/${values.month}/${values.year}`,
    comparable: Number(`${values.year}${values.month}${values.day}`)
  };
}

function validateDeadline(value) {
  if (value === null || value === undefined || String(value).trim() === '') return null;
  const input = String(value).trim();
  const today = getTodayInZurich();
  let day, month, year;
  let match = input.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/);
  if (match) {
    day = match[1].padStart(2, '0'); month = match[2].padStart(2, '0'); year = match[3];
  } else {
    match = input.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
    if (!match) return today.formatted;
    year = match[1]; month = match[2].padStart(2, '0'); day = match[3].padStart(2, '0');
  }
  const parsed = new Date(Date.UTC(Number(year), Number(month) - 1, Number(day)));
  const valid = parsed.getUTCFullYear() === Number(year) && parsed.getUTCMonth() === Number(month) - 1 && parsed.getUTCDate() === Number(day);
  if (!valid || Number(`${year}${month}${day}`) < today.comparable) return today.formatted;
  return `${day}/${month}/${year}`;
}

const subtasks = Array.isArray(ticket.subtasks)
  ? ticket.subtasks.map((subtask, index) => {
      const title = typeof subtask === 'string'
        ? subtask.trim()
        : String(subtask?.title || subtask?.text || subtask?.name || '').trim();
      return title ? { id: Date.now() + index + 1, title, text: title, completed: false } : null;
    }).filter(Boolean)
  : [];

const description = String(ticket.description)
  .replace(/\s*(?:Subtasks?|Teilaufgaben|Aufgaben)\s*:\s*[\s\S]*$/i, '')
  .replace(/\s*Dieses Ticket wurde (?:KI|AI)-generiert\.?$/i, '')
  .trim();

return [{ json: {
  sender: source.sender,
  senderRaw: source.senderRaw,
  creatorName: source.creatorName,
  subject: source.subject,
  body: source.body,
  title: String(ticket.title).trim(),
  description,
  category: ticket.category,
  priority: ticket.priority,
  deadline: validateDeadline(ticket.deadline),
  status: 'triage',
  creatorType: 'external',
  aiGenerated: true,
  subtasks
} }];

/**
 * Erstellt aus einer normalisierten E-Mail einen strukturierten Gemini-Prompt.
 * @returns {Array<{json: object}>} E-Mail-Daten und KI-Prompt
 */
const email = $('E-Mail-Daten normalisieren').first().json;
const senderRaw = String(email.sender || '').trim();
const emailMatch = senderRaw.match(/<([^<>@]+@[^<>]+)>/) || senderRaw.match(/[w.+-]+@[w.-]+.[A-Za-z]{2,}/);
const sender = emailMatch ? (emailMatch[1] || emailMatch[0]) : senderRaw;
const creatorName = senderRaw
  .replace(/<[^<>]+>/g, '')
  .replace(sender, '')
  .replace(/^["']|["']$/g, '')
  .trim();
const subject = email.subject || '';
const body = email.body || '';
const currentDate = new Intl.DateTimeFormat('de-CH', {
  timeZone: 'Europe/Zurich',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric'
}).format(new Date());

const aiPrompt = `
Analysiere die folgende E-Mail und antworte ausschließlich mit gültigem JSON.
Das heutige Datum ist: ${currentDate}

Erforderliches Format:
{
  "title": "Kurzer prägnanter Titel",
  "description": "Bereinigte Ticketbeschreibung ohne Subtasks",
  "category": "Bug oder User Story oder Technical Task",
  "priority": "urgent oder medium oder low",
  "deadline": "DD/MM/YYYY oder null",
  "subtasks": ["Erster Subtask", "Zweiter Subtask"]
}

Regeln:
- Kategorie muss Bug, User Story oder Technical Task sein.
- Priorität muss urgent, medium oder low sein.
- Erfinde keine Deadline, wenn keine angegeben wurde.
- Vergangene oder ungültige Deadlines werden auf heute (${currentDate}) korrigiert.
- Verwende für Deadlines ausschließlich DD/MM/YYYY.
- Extrahiere alle genannten Subtasks einzeln und vollständig.
- Es gibt keine Begrenzung der Subtask-Anzahl.
- Schreibe Subtasks nicht zusätzlich in die Beschreibung.
- Wenn keine Subtasks genannt wurden, verwende [].
- Antworte ohne Markdown, ausschließlich mit dem JSON-Objekt.

Absender: ${senderRaw}
Betreff: ${subject}
Nachricht: ${body}
`;

return [{ json: { sender, senderRaw, creatorName, subject, body, aiPrompt } }];

/** Prüft das tägliche Limit vor jedem Gemini-Aufruf. */
const raw = $input.first().json;
const value = typeof raw === 'number' ? raw : Number(raw?.value ?? raw?.data ?? 0);
const count = Number.isFinite(value) ? Math.max(0, Math.floor(value)) : 0;
return [{ json: { count, allowed: count < 10 } }];
